            selected: require('../assets/selected_setting_icon.png'),
          }}
        />
      </NativeTabs.Trigger>
    </NativeTabs>
  );
}
```

#### Icon rendering mode

> **important** Icon rendering mode is available in SDK 55 and later.

When using the `src` prop for custom images, you can control how the icon is rendered with the `renderingMode` prop:

- **`template`**: The icon is drawn in the tab's icon color. This is ideal for single-color icons that should match your app's color scheme.
- **`original`**: The icon keeps its own colors. This is useful for icons with gradients or multiple colors.

An image with an opaque background renders as a solid shape with `template`, so use an image with a transparent background.

```tsx src/app/_layout.tsx
import { NativeTabs } from 'expo-router/native-tabs';

export default function TabLayout() {
  return (
    <NativeTabs>
      {/* Icon with original colors preserved (e.g., for gradient or multi-color icons) */}
      <NativeTabs.Trigger name="colorful">
        <NativeTabs.Trigger.Icon
          src={require('../../../assets/colorful_icon.png')}
          renderingMode="original"
        />
      </NativeTabs.Trigger>
      {/* Icon rendered as a template */}
      <NativeTabs.Trigger name="simple">
        <NativeTabs.Trigger.Icon
          src={require('../../../assets/simple_icon.png')}
          renderingMode="template"
        />
      </NativeTabs.Trigger>
    </NativeTabs>
  );
}
```

