export default function DetailScreen() {
  usePreventZoomTransitionDismissal();
  // Dismissal gesture is now disabled - users must use navigation controls to go back
  return <View>{/* Content */}</View>;
}
```

Use the `unstable_dismissalBoundsRect` option to define a rectangle where dismissal gestures are allowed. This is useful for image viewers where you want dismissal only from the image area:

```tsx src/app/image.tsx
import { usePreventZoomTransitionDismissal } from 'expo-router';
import { View, StyleSheet } from 'react-native';
import { Image } from 'expo-image';

export default function DetailScreen() {
  // Only allow dismissal gestures that start within this rectangle
  usePreventZoomTransitionDismissal({
    unstable_dismissalBoundsRect: { minX: 100, minY: 100, maxX: 300, maxY: 300 },
  });

  return (
    <View style={styles.container}>
      {/* Visual indicator of the dismissal zone (for demonstration) */}
      <View style={styles.dismissalZone} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  image: {
    flex: 1,
  },
  dismissalZone: {
    position: 'absolute',
    left: 100,
    top: 100,
    width: 200, // maxX - minX = 300 - 100
    height: 200, // maxY - minY = 300 - 100
    borderWidth: 2,
    borderColor: 'rgba(0, 122, 255, 0.5)',
    borderStyle: 'dashed',
    backgroundColor: 'rgba(0, 122, 255, 0.1)',
  },
});
```

If the typical starting point for your app is a set of tabs, but one or more tabs may have more than one screen associated with it, nesting a stack navigator inside of a tab is often the way to go. This pattern often results in intuitive URLs and scales well to desktop web apps, where the primary tabs are often always visible.

Consider the following navigation tree:

<FileTree
  files={[
    ['src/app/(tabs)/\_layout.tsx'],
    ['src/app/(tabs)/index.tsx', 'single page tab'],
    ['src/app/(tabs)/feed/\_layout.tsx', 'tab with a stack inside'],
    ['src/app/(tabs)/feed/index.tsx'],
    ['src/app/(tabs)/feed/[postId].tsx'],
    ['src/app/(tabs)/settings.tsx', 'single page tab'],
  ]}
/>

In the **src/app/(tabs)/\_layout.tsx** file, return a `Tabs` component:

```tsx src/app/(tabs)/_layout.tsx
import { Tabs } from 'expo-router';

export default function TabLayout() {
  return (
    /* @info Each navigator adds it's own header, so you will likely want to hide the header in the outer navigator. */
    <Tabs screenOptions={{ headerShown: false }}>
    /* @end */
      <Tabs.Screen name="index" options={{ title: 'Home' }} />
      <Tabs.Screen name="feed" options={{ title: 'Feed' }} />
      <Tabs.Screen name="settings" options={{ title: 'Settings' }} />
    </Tabs>
  );
}
```

In the **src/app/(tabs)/feed/\_layout.tsx** file, return a `Stack` component:

```tsx src/app/(tabs)/feed/_layout.tsx
import { Stack } from 'expo-router';

/* @info Setting `anchor` ensures that direct links deep into the stack still push the index route onto the stack first. */
export const unstable_settings = {
  anchor: 'index',
};
/* @end */

export default function FeedLayout() {
  return <Stack />;
}
```

Now, within the **src/app/(tabs)/feed** directory, you can have `Link` components that point to different posts (for example, `/feed/123`). Those links will push the `feed/[postId]` route onto the stack, leaving the tab navigator visible.

You can also navigate from any other tab to a post in the feed tab with the same URL. Use `withAnchor` in conjunction with `anchor` to ensure that the `feed/index` route is always the first screen in the stack:

```tsx src/app/(tabs)/feed/index.tsx
<Link href="/feed/123" withAnchor>
  Go to post
</Link>
```

You can also nest tabs inside of an outer stack navigator. That is often more useful for displaying modals over the tabs.

A `Link` to a URL that belongs to another tab switches tabs, and the back button then pops the stack inside that tab. In the example above, opening `/feed/123` from the Settings tab lands on the post in the Feed tab. Going back returns to `feed/index`, not to Settings.

With [native tabs](/router/advanced/native-tabs/), the tab navigator loads every tab as soon as it mounts. A tab that contains a stack is already sitting at that stack's first screen before you link into it. That screen ends up underneath the one you linked to whether or not you pass `withAnchor`.

If you want the back button to return to the screen you came from, keep the detail route out of the tabs and push it from an outer stack instead:

<FileTree
  files={[
    ['src/app/\_layout.tsx', 'stack that contains the tabs'],
    ['src/app/(tabs)/\_layout.tsx'],
    ['src/app/(tabs)/index.tsx'],
    ['src/app/(tabs)/feed/\_layout.tsx'],
    ['src/app/(tabs)/feed/index.tsx'],
    ['src/app/(tabs)/settings.tsx'],
    ['src/app/feed/[postId].tsx', 'pushed above the tab bar'],
  ]}
/>

```tsx src/app/_layout.tsx
import { Stack } from 'expo-router';

export default function RootLayout() {
  return (
    <Stack>
      <Stack.Screen name="(tabs)" options={{ headerShown: false }} />
      <Stack.Screen name="feed/[postId]" options={{ title: 'Post' }} />
    </Stack>
  );
}
```

Route groups can be used to share a single screen between two different tabs. Consider a navigation tree that has a Feed tab and a Search tab, and they both share pages for viewing a user profile:

<FileTree
  files={[
    ['src/app/(tabs)/\_layout.tsx'],
    ['src/app/(tabs)/(feed)/index.tsx', 'default route'],
    ['src/app/(tabs)/(search)/search.tsx'],
    ['src/app/(tabs)/(feed,search)/\_layout.tsx', 'layout shared between the two tabs'],
    ['src/app/(tabs)/(feed,search)/users/[username].tsx', 'shared user profile page'],
  ]}
/>

Each of the tabs is put in a group so you can define a third directory that shares routes between two groups (**src/app/(tabs)/(feed,search)/**). Even with the extra layer, **src/app/(tabs)/(feed)/index.tsx** is still the nearest index, so it will be the default route.

```tsx src/app/(tabs)/_layout.tsx
import { Tabs } from 'expo-router';

export default function TabLayout() {
  return (
    <Tabs>
      <Tabs.Screen name="(feed)" options={{ title: 'Feed' }} />
      <Tabs.Screen name="(search)" options={{ title: 'Search' }} />
    </Tabs>
  );
}
```

Both the `(feed)` and `(search)` route groups contain stacks, so they can also share a single layout:

```tsx src/app/(tabs)/(feed,search)/_layout.tsx
import { Stack } from 'expo-router';

export default function SharedLayout() {
  return <Stack />;
}
```

```tsx src/app/_layout.tsx
import { Stack } from 'expo-router';
import { useAuthState } from '@/utils/authState';

export default function RootLayout() {
  const { isLoggedIn } = useAuthState();

  return (
    <Stack>
      <Stack.Protected guard={isLoggedIn}>
        <Stack.Screen name="(tabs)" />
        <Stack.Screen name="modal" />
      </Stack.Protected>

      <Stack.Protected guard={!isLoggedIn}>
        <Stack.Screen name="sign-in" />
        <Stack.Screen name="create-account" />
      </Stack.Protected>
    </Stack>
  );
}
```

This way, you can fetch your auth state from a store and show the appropriate screens. If the auth state changes, the layout will re-render, so if `isLoggedIn` changes from `false` to `true`, the app will automatically navigate to the root of the `(tabs)` group.

Another benefit of protected routes is that they are checked even if you deep link into a page directly. For example, if an unauthenticated user deep links into the modal screen above, they will be redirected to the sign-in page.

Protected routes can also be used to conditionally show bottom tabs. In this example, the `vip` tab will only be shown to authenticated users who are VIP members:

```tsx src/app/(tabs)/_layout.tsx
import { Stack } from 'expo-router';
import { useAuthState } from '@/utils/authState';

export default function TabsLayout() {
  const { isVip } = useAuthState();

  return (
    <Tabs>
      <Tabs.Screen name="index" />

      <Tabs.Protected guard={isVip}>
        <Tabs.Screen name="vip" />
      </Tabs.Protected>

      <Tabs.Screen name="settings" />
    </Tabs>
  );
}
```

<BoxLink
  title="Expo Router authentication"
  description="Follow an in-depth guide for implementing authentication using protected routes."
  href="/router/advanced/authentication/"
  Icon={RouterLogo}
/>

Separating your navigation states into distinct routes is meant to serve you and your app. Sometimes the best pattern for the job will not involve navigating to another route at all. Since layout files are just React components, you can use them to display all sorts of UI around, besides, or instead of a navigator.

Thinking back to authentication, the protected route setup works great if the user should simply not be able to visit certain pages without logging in. But what about when unauthenticated users can browse an app in read-only mode? In that case, you might want to show a login modal over the app, rather than redirecting the user to a login page:

```tsx src/app/(logged-in)/_layout.tsx
import { Modal } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Stack } from 'expo-router';

export default function Layout() {
  const isAuthenticated = /* check for valid auth token / session */

  return (
    <SafeAreaView>
      <Stack />
      <Modal visible={!isAuthenticated}>{/* login UX */}</Modal>
    </SafeAreaView>
  );
}
```

<BoxLink
  title="Modals in Expo Router"
  description="Learn multiple patterns for displaying modals in Expo Router, including using a modal inside of a layout file."
  href="/router/advanced/modals/"
  Icon={RouterLogo}
/>

Virtually every app will have a **\_layout.tsx** file directly inside the **src/app** directory. This is the root layout and represents the entry point for your navigation. In addition to describing the top-level navigator for your app, this file is where you would put initialization code that may have previously gone inside an **App.jsx** file, such as loading fonts, interacting with the splash screen, or adding context providers.

Here's an example root layout:

```tsx src/app/_layout.tsx
import { useFonts } from 'expo-font';
import { Stack } from 'expo-router';
import * as SplashScreen from 'expo-splash-screen';
import { useEffect } from 'react';

SplashScreen.preventAutoHideAsync();

export default function RootLayout() {
  const [loaded] = useFonts({
    SpaceMono: require('@/assets/fonts/SpaceMono-Regular.ttf'),
  });

  useEffect(() => {
    if (loaded) {
      SplashScreen.hide();
    }
  }, [loaded]);

  if (!loaded) {
    return null;
  }

  return <Stack />;
}
```

The above example shows the splash screen initially and then renders a stack navigator once the fonts are loaded, which will cause your app to proceed to the initial route.

You can implement a stack navigator in your root layout, as shown above, or in any other layout file inside a directory. Let's suppose you have a file structure with a stack inside of a directory:

<FileTree
  files={[
    ['src/app/products/\_layout.tsx'],
    ['src/app/products/index.tsx'],
    ['src/app/products/[productId].tsx'],
    ['src/app/products/accessories/index.tsx'],
  ]}
/>

If you want everything inside the **src/app/products** directory to be arranged in a stack relationship, inside the **\_layout.tsx** file, return a `Stack` component:

```tsx src/app/products/_layout.tsx
import { Stack } from 'expo-router';

export default function StackLayout() {
  return <Stack />;
}
```

When you navigate to `/products`, it will first go to the default route, which is **products/index.tsx**. If you navigate to `/products/123`, then that page will be pushed onto the stack. By default, the stack will render a back button in the header that will pop the current page off the stack, returning the user to the previous page. Even when a page isn't visible, if it is still pushed onto the stack, it is still being rendered.

The `Stack` component arranges routes in a stack. Files inside the directory automatically become eligible routes, so you do not have to define every screen in the navigator. To set screen options, add a `Stack.Screen` component inside the `Stack` component. Its `name` prop should match the route name so that Expo Router can map the route to its component automatically. See [Stack](/router/advanced/stack/) for more options:

```tsx src/app/products/_layout.tsx
import { Stack } from 'expo-router';

export default function StackLayout() {
  return (
    <Stack>
      <Stack.Screen name="[productId]" options={{ headerShown: false }} />
    </Stack>
  );
}
```

While it is possible to nest navigators, be sure to only do so when it is truly needed. In the above example, if you want to push **products/accessories/index.tsx** onto the stack, it's not necessary to have an additional **\_layout.tsx** in the **accessories** directory with a `Stack` navigator. That would define another stack inside the first one. It is fine to add directories that only affect the URL, otherwise, use the same navigator as the parent directory.

You can implement a JavaScript-based tab navigator in a layout file using the `Tabs` component. All the routes directly inside that directory will be treated as tabs. Consider the following file structure:

<FileTree
  files={[
    ['src/app/(tabs)/\_layout.tsx'],
    ['src/app/(tabs)/index.tsx'],
    ['src/app/(tabs)/feed.tsx'],
    ['src/app/(tabs)/profile.tsx'],
  ]}
/>

In the **\_layout.tsx** file, return a `Tabs` component:

```tsx src/app/(tabs)/_layout.tsx|collapseHeight=480
import { Tabs } from 'expo-router';
import MaterialIcons from '@expo/vector-icons/MaterialIcons';

export default function TabLayout() {
  return (
    <Tabs>
      <Tabs.Screen
        name="index"
        options={{
          title: 'Home',
          tabBarIcon: ({ color }) => <MaterialIcons size={28} name="house.fill" color={color} />,
        }}
      />
      <Tabs.Screen name="feed" options={{ title: 'Feed' }} />
      <Tabs.Screen name="profile" options={{ title: 'Profile' }} />
    </Tabs>
  );
}
```

This will cause the **index.tsx**, **feed.tsx**, and **profile.tsx** files to appear together in the same JavaScript tabs navigator. See [Tabs](/router/advanced/tabs/) for its tab bar and screen options.

Since native tabs are only available on Android and iOS, a common pattern is to use [platform-specific file extensions](/router/advanced/platform-specific-modules/) to provide different tab implementations for native and web. The root layout renders a tab component, and Expo's module resolution automatically picks the correct file based on the platform.

<FileTree
  files={[
    ['src/app/\_layout.tsx'],
    ['src/app/index.tsx'],
    ['src/app/explore.tsx'],
    ['src/components/app-tabs.native.tsx', 'Native tabs (Android and iOS)'],
    ['src/components/app-tabs.tsx', 'Custom tabs (web)'],
  ]}
/>

The root layout imports and renders the `AppTabs` component. **app-tabs.native.tsx** is used on Android and iOS, and **app-tabs.tsx** on web:

```tsx src/app/_layout.tsx
import AppTabs from '@/components/app-tabs';

export default function RootLayout() {
  return <AppTabs />;
}
```

On Android and iOS, **app-tabs.native.tsx** uses [native tabs](/router/advanced/native-tabs/):

```tsx src/components/app-tabs.native.tsx
import { NativeTabs } from 'expo-router/native-tabs';

export default function AppTabs() {
  return (
    <NativeTabs>
      <NativeTabs.Trigger name="index">
        <NativeTabs.Trigger.Label>Home</NativeTabs.Trigger.Label>
        <NativeTabs.Trigger.Icon src={require('@/assets/images/tabIcons/home.png')} />
      </NativeTabs.Trigger>
      <NativeTabs.Trigger name="explore">
        <NativeTabs.Trigger.Label>Explore</NativeTabs.Trigger.Label>
        <NativeTabs.Trigger.Icon src={require('@/assets/images/tabIcons/explore.png')} />
      </NativeTabs.Trigger>
    </NativeTabs>
  );
}
```

On web, **app-tabs.tsx** uses [custom tabs](/router/advanced/custom-tabs/) from `expo-router/ui`, which are unstyled and flexible components:

```tsx src/components/app-tabs.tsx
import { Tabs, TabList, TabTrigger, TabSlot } from 'expo-router/ui';

export default function AppTabs() {
  return (
    <Tabs>
      <TabSlot />
      <TabList>
        <TabTrigger name="index" href="/">
          Home
        </TabTrigger>
        <TabTrigger name="explore" href="/explore">
          Explore
        </TabTrigger>
      </TabList>
    </Tabs>
  );
}
```

In some cases, you may want a layout without a navigator. This is helpful for adding a header or footer around the current route, or for displaying a modal over any route inside a directory. In this case, you can use the `Slot` component, which serves as a placeholder for the current child route.

Consider the following file structure:

<FileTree
  files={[
    ['src/app/social/\_layout.tsx'],
    ['src/app/social/index.tsx'],
    ['src/app/social/feed.tsx'],
    ['src/app/social/profile.tsx'],
  ]}
/>

For example, you may want to wrap any route inside the **social** directory with a header and footer, but you want navigating between the pages to simply replace the current page rather than pushing new pages onto a stack, which can then later be popped off with a "back" navigation action. In the **\_layout.tsx** file, return a `Slot` component surrounded by your header and footer:

```tsx src/app/social/_layout.tsx
import { Slot } from 'expo-router';

export default function Layout() {
  return (
    <>
      <Header />
      <Slot />
      <Footer />
    </>
  );
}
```

Like in React Navigation, you can call a function from an `onPress` handler to navigate to another page. In Expo Router, you can use the `useRouter` hook to access navigation functions:

```tsx
import { useRouter } from 'expo-router';
import { Button } from 'react-native';

export default function Home() {
  const router = useRouter();

  return <Button title="Go to About" onPress={() => router.navigate('/about')} />;
}
```

Expo Router apps default to stack navigation, where navigating to a new route pushes a screen onto a stack, and backing out of that route pops it off the stack. Usually, you would want to use the `router.navigate` function. This will either push a new page onto the stack or unwind to an existing route on the stack. However, you can also call `router.push` to explicitly push a new page onto the stack, `router.back` to go back to the previous page, or `router.replace` to replace the current page on the stack.

With Expo Router, you refer to pages by their URL, or their position relative to the **src/app** directory. Check out the following file structure and how you would navigate to each page:

The typical way to link to a page in Expo Router is to use links like web apps. Expo Router has a `Link` component for navigating between pages, where the `href` is the same route you would use in `router.navigate`:

```tsx src/app/index.tsx
import { View } from 'react-native';
/* @info Import the `Link` React component from `expo-router`. */
import { Link } from 'expo-router';
/* @end */

export default function Page() {
  return (
    <View>
      /* @info Tapping this will link to the **about** page. */
      <Link href="/about">About</Link>
      /* @end */
    </View>
  );
}
```

By default, the `Link` component renders its children inside a `<Text>` element. This means non-text children (such as `View`) may have unexpected layout behavior. To have full control over the layout, use the `asChild` prop with a `Pressable` or another component that accepts `onPress`/`onClick` props:

```tsx
import { Pressable, Text } from 'react-native';
import { Link } from 'expo-router';

export default function Page() {
  return (
    /* @info The `onPress` event that navigates to `/other` will be passed to `Pressable`. */
    <Link href="/other" asChild>
    /* @end */
      <Pressable>
        <Text>Home</Text>
      </Pressable>
    </Link>
  );
}
```

All variables in the link URL are accessible to the receiving page via the `useLocalSearchParams` hook. This hook returns an object with all the URL parameters, including those passed as `params`.

For example, if you have a link like this:

```tsx
<Link href="/users?limit=20">View users</Link>
```

Then you can read the parameters on the other end like this:

```tsx
import { useLocalSearchParams } from 'expo-router';
import { View, Text } from 'react-native';

export default function Users() {
  const { id, limit } = useLocalSearchParams();

  return (
    <View>
      <Text>User ID: {id}</Text>
      <Text>Limit: {limit}</Text>
    </View>
  );
}
```

You can immediately redirect to another route from a page or layout with the `Redirect` component. This functions like the `replace` imperative navigation function. A redirect will navigate to the new route without rendering the current page.

```tsx
import { Redirect } from 'expo-router';

export default function Page() {
  return <Redirect href="/about" />;
}
```

The `prefetch` prop on a `<Link />` component enables prefetching of the target screen when the component is rendered. This allows for faster navigation by preparing the screen in advance.

```tsx
import { Link } from 'expo-router';

export default function Page() {
  return <Link href="/about" prefetch />;
}
```

When `prefetch` is set, Expo Router will attempt to render the target screen off-screen. The exact behavior depends on the type of navigator used:

- **Expo Router Navigators**: Render the target screen off-screen to enable preloading.
- **Custom Navigators**: May implement prefetching differently or not support it at all.

When a screen is preloaded in a stack navigator, it will have a few limitations:

- It cannot use the imperative `router` API.
- It cannot update options with `useNavigation().setOptions()`
- It cannot listen to events from the navigator (for example focus, tabPress, and so on).

The navigation object will be updated once you navigate to the screen. So if you have an event listener in a useEffect hook, and have a dependency on navigation, it will add any listeners when the screen is navigated to:

```tsx
const navigation = useNavigation();

useEffect(() => {
  const unsubscribe = navigation.addListener('tabPress', () => {
    // do something
  });

  return () => {
    unsubscribe();
  };
}, [navigation]);
```

Similarly, for dispatching actions or updating options, you can check if the screen is focused before doing so:

```tsx
const navigation = useNavigation();

if (navigation.isFocused()) {
  navigation.setOptions({ title: 'Updated title' });
}
```

When opening a deep link to a page in your app, you will likely want back navigation to work as if the user navigated to the page from your home page. To do this, you can specify an `anchor` configuration, which defines the page in a layout that should be loaded before the deep linked page.

Consider the following file structure:

<FileTree
  files={[
    ['src/app/index.tsx'],
    ['src/app/stack/index.tsx'],
    ['src/app/stack/second.tsx'],
    ['src/app/stack/\_layout.tsx'],
  ]}
/>

`stack` is a stack navigator, and `/stack/index` is always the first route in the stack.

To ensure that `/stack/index` is always loaded first, even if the user deep links to `/stack/second`, you can set the `anchor` in **src/app/stack/\_layout.tsx**:

```tsx
export const unstable_settings = {
  // Ensure any route can link back to `/`
  anchor: 'index',
};
```

By default, the `anchor` is only considered when deep linking and not during navigation within your app. However, you can use the `withAnchor` prop on `Link` to force the anchor route to be loaded when navigating directly into another stack inside your app.

So, if **src/app/index.tsx** contained a link to `/stack/second`, add the `withAnchor` prop to ensure that `/stack/index` is loaded first, which will cause the user to go back to `/stack/index` when they press the back button from `/stack/second`:

Expo Router enables fine-tuned error handling to enable a more opinionated data-loading strategy in the future.

<ContentSpotlight
  alt="Using ErrorBoundary in Expo Router to catch errors in a route component."
  src="/static/images/expo-router/error-boundaries.webp"
  className="max-w-[720px]"
/>

You can export a nested [`ErrorBoundary`](/versions/latest/sdk/router/#errorboundary) component from any route to intercept and format component-level errors using [React Error Boundaries](https://react.dev/reference/react/Component#catching-rendering-errors-with-an-error-boundary):

```tsx src/app/home.tsx
import { View, Text } from 'react-native';
import { type ErrorBoundaryProps } from 'expo-router';

/* @info */
export function ErrorBoundary({ error, retry }: ErrorBoundaryProps) {
/* @end */
  return (
    <View style={{ flex: 1, backgroundColor: "red" }}>
      <Text>{error.message}</Text>
      <Text onPress={retry}>Try Again?</Text>
    </View>
  );
}

export default function Page() { ... }
```

When you export an `ErrorBoundary` the route will be wrapped with a React Error Boundary effectively:

```tsx Virtual
function Route({ ErrorBoundary, Component }) {
  return (
    <Try catch={ErrorBoundary}>
      <Component />
    </Try>
  );
}
```

A screen error boundary keeps navigator UI, such as headers and tab bars, mounted when a screen throws. Configure it on a layout or navigator:

```tsx src/app/_layout.tsx
import { Stack, type ErrorBoundaryProps } from 'expo-router';
import { Text } from 'react-native';

function ScreenErrorBoundary({ error, retry }: ErrorBoundaryProps) {
  return <Text onPress={retry}>Try again: {error.message}</Text>;
}

// Configure the boundary for screens in this layout and nested layouts.
export const unstable_settings = {
  screenErrorBoundary: ScreenErrorBoundary,
};

export default function Layout() {
  return <Stack />;
}
```

Alternatively, configure the boundary on the navigator:

```tsx src/app/_layout.tsx
import { Stack, type ErrorBoundaryProps } from 'expo-router';
import { Text } from 'react-native';

function ScreenErrorBoundary({ error, retry }: ErrorBoundaryProps) {
  return <Text onPress={retry}>Try again: {error.message}</Text>;
}

// This prop overrides unstable_settings.screenErrorBoundary for the same screens.
export default function Layout() {
  return <Stack unstable_screenErrorBoundary={ScreenErrorBoundary} />;
}
```

Expo Router applies error boundaries in the following order:

1. `ErrorBoundary` exported from the screen
2. Navigator-level prop (for example, `Stack`)
3. `unstable_settings.screenErrorBoundary` declared in the **\_layout.tsx** file

> **important** Custom suspense fallbacks are available in SDK 56 and later.

In SDK 58 and later, [async routes](/router/web/async-routes/) are enabled by default on web and use the default loading fallback instead of custom `SuspenseFallback` exports. To use the examples below on web, set `asyncRoutes: { web: false }` in the `expo-router` config plugin in your [app config](/workflow/configuration/). This restores synchronous route loading and custom fallback support. Native defaults are unchanged.

Expo Router wraps each route in a [React Suspense](https://react.dev/reference/react/Suspense) boundary. You can export a [`SuspenseFallback`](/versions/latest/sdk/router/#suspensefallback) component from a layout file to customize the loading UI shown while any child route is suspended:

```tsx src/app/_layout.tsx
import { ActivityIndicator, View } from 'react-native';
import { Stack } from 'expo-router';

export function SuspenseFallback() {
  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <ActivityIndicator size="large" />
    </View>
  );
}

export default function RootLayout() {
  return <Stack />;
}
```

> When multiple parent layouts define a fallback, the nearest parent takes precedence.

The [`SuspenseFallback`](/versions/latest/sdk/router/#suspensefallback) component receives `route` and `params` props. You can use `params` to display context-specific loading states for dynamic routes, for example:

```tsx src/app/(app)/_layout.tsx
import { ActivityIndicator, Text, View } from 'react-native';
import { Stack, type SuspenseFallbackProps } from 'expo-router';

export function SuspenseFallback({ params }: SuspenseFallbackProps) {
  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>Loading profile {params.id}...</Text>
      <ActivityIndicator size="large" />
    </View>
  );
}

export default function AppLayout() {
  return <Stack />;
}
```

